      "name": "Cajado Zumbi",
      "description": "Um bastão de zumbi está gravado com o rosto podre de um humanóide morto-vivo fazendo uma careta de terror e consternação esculpido em cima dele. As magias de convocar mortos-vivos do cajado podem invocar apenas mortos-vivos que tenham carne e um modificador de Inteligência de –4 ou inferior.\nAtivar lançar uma magia\nEfeito Você gasta um número de cargas do cajado para conjurar uma magia de sua lista. Se você conjurar convocar mortos-vivos, você também pode conjurar proteger companheiro no lacaio resultante como uma ação livre.\n• Cantrip Proteger Companheiro\n• Generosidade do 1º Necromante, Convocar Mortos-vivos\n• 2º Sacrifício Final, Convocar Mortos-Vivos\nRequisitos de Criação Forneça uma conjuração de todas as graduações listadas de todas as magias listadas.",
