      "name": "Espelho Enigma",
      "description": "A névoa enche o vidro deste pequeno espelho de mão circular, criando padrões estranhos nas mechas cinzentas mutáveis. A parte de trás do espelho traz uma escrita fluida gravada em um idioma desconhecido. A CD de qualquer magia lançado ao ativar este item é 23.\n• Armadura Depois de lançar uma magia de ilusão ativando o espelho, escolha um aliado dentro de 30 pés (9 metros). Esse aliado fica Oculto como se fosse visto em um espelho embaçado, até o final do seu próximo turno.\n• Arma Depois de lançar uma magia de ilusão ativando o espelho, cópias ilusórias da arma giram no ar ao seu redor. Você é afetado pela magia Bosque de Facas até o final do seu próximo turno. A magia termina se você parar de empunhar a arma afixada.\nAtivar lançar uma magia\nEfeito Você lança Proteção Proibidora.\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito que você lança Blur",
